print("✨ Harry Potter Vocabulary Guide 🪄")

while True:
    print("Wizarding World(WW)⚡Magic-Users(MU)⚡Blood Status(BS)⚡Cool Abilities(CA)⚡Travel(T)⚡Currency Coins(CC)")
    print("Hogwarts(H)⚡Education(E)⚡Spells(S)⚡Potions/Plants(PP)⚡Creatures(C)⚡Activities(A)⚡Professions(P)")
    print("Places/Objects(PO)⚡Deathly Hallows(DH)⚡Unforgivable Curses(UC)⚡Dark Stuff(DS)")

    category = input("Enter a category's shortened form to learn its vocabulary: ").upper()
    print("~ " * 50)

    if category in vocab:
        print(f"You chose: {category}")
        print("Here are the vocabulary words in this category:")
        print(f"{vocab[category]}")
        print("~ " * 50)
    else:
        print("Category not found, try again.")
        print("~ " * 50)
        continue

    again = input("Would you like to explore another category? Yes(Y) or No(N) : ").upper()
    print("~ " * 50)

    if again == "N":
        print("⚡Thanks for exploring the Wizarding World! Mischief managed!📜👣")
        break
